    "d5.title": "Average CO₂ emissions of new cars in Europe",
    "d5.lead": "An analysis of the average CO₂ emissions of new passenger cars registered in Europe, geographically by country and also by carmaker group, brand and powertrain type (petrol, diesel, hybrid and so on). A selector switches the metric between average emissions and registrations. There is one dashboard for 2024 and another for 2023.",
    "d5.record": "<div><dt>Period</dt><dd>2023 and 2024</dd></div> <div><dt>Updated</dt><dd>Yearly</dd></div> <div><dt>Source</dt><dd><a href=\"https://www.eea.europa.eu/en/datahub/datahubitem-view/fa8b1229-3db6-495d-b18e-9c9b3267c02b?activeAccordion=1094576\" target=\"_blank\" rel=\"noopener\">European Environment Agency</a></dd></div>",
    "d5.statsLabel": "2024 figures",
    "d5.stats": "<li class=\"stat\"><span class=\"stat__value\">10.78<small> M</small></span><span class=\"stat__text\">new passenger cars registered in Europe</span></li> <li class=\"stat\"><span class=\"stat__value\">106.9<small> g/km</small></span><span class=\"stat__text\">average CO₂ per new vehicle</span></li>",
