    "reports.doc2StatsAria": "Txostenaren zenbait datu (2026ko urtarrila–apirila)",
    "reports.doc2Stats": "<li><b>% 25,58</b><span>elektrikoen (BEV) kuota partikularren turismoetan</span></li> <li><b>1.</b><span>Espainiako probintzia, BEV kuota handienarekin</span></li> <li><b>85,55</b><span>g/km CO₂ batez beste, herrialdeko txikiena</span></li>",
    "navarra.title": "Nafarroa, arrakasta-kasua auto elektrikoaren hedapenean",
    "navarra.lead": "2026ko urtarriletik apirilera, Nafarroan partikularrek matrikulatutako lau turismo berritatik bat % 100 elektrikoa izan zen: Espainiako kuotarik handiena, gainerako probintzietan baino bi aldiz handiagoa. DGTren mikrodatuekin aztertu dut zein marka eta modelo dauden horren atzean, nola hazi den merkatua eta horrek guztiak zer eragin duen CO₂ isurietan.",
    "navarra.record": "<div><dt>Aldia</dt><dd>2026ko urtarrila–apirila, 2025eko aldi berarekin alderatuta</dd></div> <div><dt>Irismena</dt><dd>Partikularrek matrikulatutako turismo eta lur orotariko berriak</dd></div> <div><dt>Iturria</dt><dd><a href=\"https://www.dgt.es/menusecundario/dgt-en-cifras/dgt-en-cifras-resultados/dgt-en-cifras-detalle/Microdatos-de-Matriculaciones-de-Vehiculos-mensual/\" target=\"_blank\" rel=\"noopener\">DGTren matrikulazioen mikrodatuak</a></dd></div>",
    "navarra.statsLabel": "Nafarroa, 2026ko urtarriletik apirilera",
    "navarra.stats": "<li class=\"stat\"><span class=\"stat__value\">% 25,58</span><span class=\"stat__text\">elektrikoak (BEV), Espainiako kuotarik handiena; gainerako probintzietan % 12,59 da</span></li> <li class=\"stat\"><span class=\"stat__value\">85,55<small> g/km</small></span><span class=\"stat__text\">CO₂ batez beste auto berriko, Espainiako txikiena; Madril da bigarrena, 89,19rekin</span></li> <li class=\"stat\"><span class=\"stat__value\">+% 100</span><span class=\"stat__text\">elektrikoen matrikulazioak 2025eko urtarrila–apirilarekin alderatuta: bikoiztu egin dira</span></li> <li class=\"stat\"><span class=\"stat__value\">% 35,29</span><span class=\"stat__text\">entxufagarriak: % 25,58 elektrikoak eta % 9,71 hibrido entxufagarriak (PHEV)</span></li>",
