    "d3.title": "El parc automobilístic a Espanya",
    "d3.lead": "Analitza tots els vehicles en circulació a Espanya a l’últim dia de cada any, del 2021 al 2025: distintiu ambiental, antiguitat, emissions mitjanes de CO₂ i any de primera matriculació. La portada dona accés a dos quadres de comandament: l’evolució anual del parc i una anàlisi per motorització, marca i província.",
    "d3.record": "<div><dt>Període</dt><dd>Del 2021 al 2025, a 31 de desembre</dd></div> <div><dt>Actualització</dt><dd>Anual, cap a l’abril</dd></div> <div><dt>Font</dt><dd><a href=\"https://www.dgt.es/menusecundario/dgt-en-cifras/dgt-en-cifras-resultados/dgt-en-cifras-detalle/Microdatos-de-parque-de-vehiculos-Anual/\" target=\"_blank\" rel=\"noopener\">Microdades del parc de vehicles de la DGT</a></dd></div>",
    "d3.video1t": "Parc automobilístic d’Espanya",
    "d3.video1": "<svg aria-hidden=\"true\"><use href=\"#i-play\"/></svg>Vídeo explicatiu",
    "video.valdesParkT": "El parc automobilístic, amb Luis Valdés",
    "video.valdes": "<svg aria-hidden=\"true\"><use href=\"#i-play\"/></svg>Vídeo amb Luis Valdés",
    "d3.statsLabel": "Xifres del parc a 31 de desembre del 2025",
    "d3.stats": "<li class=\"stat\"><span class=\"stat__value\">38,64<small> M</small></span><span class=\"stat__text\">de vehicles formen el parc espanyol</span></li> <li class=\"stat\"><span class=\"stat__value\">15,87<small> anys</small></span><span class=\"stat__text\">d’antiguitat mitjana: un parc molt envellit</span></li> <li class=\"stat\"><span class=\"stat__value\">2,16&nbsp;%</span><span class=\"stat__text\">té etiqueta ZERO (1,14&nbsp;% BEV i 1,02&nbsp;% híbrids endollables)</span></li> <li class=\"stat\"><span class=\"stat__value\">104,9<small> g/km</small></span><span class=\"stat__text\">de CO₂ de mitjana al parc (112,66 en turismes)</span></li>",
    "d3.vizTitle": "Parc automobilístic a Espanya",
    "d3.tabsAria": "Quadres de comandament del parc automobilístic",
    "d3.tab1": "Portada",
    "d3.tab1d": "Foto del parc a 31 de desembre: distintiu ambiental, antiguitat mitjana, emissions de CO₂ i any de primera matriculació.",
    "d3.tab2": "Evolució per anys",
    "d3.tab2d": "Composició del parc en cada any per tipus de motorització i data de matriculació. Cada fila representa el parc a l’últim dia de l’any.",
    "d3.tab3": "Anàlisi del parc",
    "d3.tab3d": "Mètriques del parc per motorització, marca, província…, amb selector de mètrica: nombre de vehicles, emissions mitjanes de CO₂, antiguitat…",
    "d4.title": "Transferències de turismes i tot terrenys",
    "d4.lead": "Analitza el mercat d’ocasió: les transferències de turismes i tot terrenys a Espanya des del 2022. Segueix la mateixa estructura que l’anàlisi de matriculacions —portada amb la visió general i sis quadres de comandament temàtics—, afegint l’antiguitat mitjana del vehicle transferit.",
    "d4.record": "<div><dt>Període</dt><dd>Des del 2022</dd></div> <div><dt>Actualització</dt><dd>Mensual, el dia 15</dd></div> <div><dt>Font</dt><dd><a href=\"https://www.dgt.es/menusecundario/dgt-en-cifras/dgt-en-cifras-resultados/dgt-en-cifras-detalle/Microdatos-de-Transferencias-de-Vehiculos-mensual/\" target=\"_blank\" rel=\"noopener\">Microdades de transferències de la DGT</a></dd></div>",
    "video.valdesUsedT": "El mercat de segona mà, amb Luis Valdés",
    "d4.video1": "<svg aria-hidden=\"true\"><use href=\"#i-play\"/></svg>Vídeo amb Luis Valdés",
    "d4.stats": "<li class=\"stat\"><span class=\"stat__value\">3,36<small> M</small></span><span class=\"stat__text\">de transferències el 2025, un 33,52&nbsp;% més que el 2022</span></li> <li class=\"stat\"><span class=\"stat__value\">48,06&nbsp;%</span><span class=\"stat__text\">dels cotxes transferits són dièsel (56,1&nbsp;% el 2022)</span></li> <li class=\"stat\"><span class=\"stat__value\">1,29&nbsp;%</span><span class=\"stat__text\">quota d’elèctrics (BEV) al mercat d’ocasió</span></li> <li class=\"stat\"><span class=\"stat__value\">11,7<small> anys</small></span><span class=\"stat__text\">d’antiguitat mitjana del vehicle transferit</span></li>",
